    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        List<String> t = new ArrayList<>();
        while (st.hasMoreTokens()) t.add(st.nextToken());
        TreeNode root = new TreeNode(Integer.parseInt(t.get(0)));
        Deque<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < t.size()) {
            TreeNode node = q.poll();
            if (i < t.size()) {
                if (!t.get(i).equals("null")) {
                    node.left = new TreeNode(Integer.parseInt(t.get(i)));
                    q.add(node.left);
                }
                i++;
            }
            if (i < t.size()) {
                if (!t.get(i).equals("null")) {
                    node.right = new TreeNode(Integer.parseInt(t.get(i)));
                    q.add(node.right);
                }
                i++;
            }
        }
        StringBuilder sb = new StringBuilder();
        for (List<Integer> col : verticalOrder(root)) {
            for (int j = 0; j < col.size(); j++) sb.append(col.get(j)).append(j + 1 < col.size() ? " " : "\n");
        }
        System.out.print(sb);
    }
}
